INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7284562, 1135069, 16241, '<td valign="top">Stingray</td>', 'Stingray', '2014-11-12 01:48:06.000000', NULL, 1),
(7284589, 1135301, 141826, '<td valign="top">10++</td>', '10++', '2014-11-12 03:54:36.000000', NULL, 1),
(7284604, 1135346, 54446, '<td valign="top">Good photo of someone else''s art.</td>', 'Good photo of someone else''s art.', '2014-11-12 05:46:36.000000', NULL, 1),
(7284622, 1135309, 163081, '<td valign="top">Love your title. The picture is awesome. This is my favorite for the challenge. 9 from me</td>', 'Love your title. The picture is awesome. This is my favorite for the challenge. 9 from me', '2014-11-12 07:25:49.000000', NULL, 1),
(7284662, 1135162, 68020, '<td valign="top">would have loved to see this in B&amp;W...</td>', 'would have loved to see this in B&W...', '2014-11-12 08:59:48.000000', NULL, 1),
(7284693, 1135309, 170281, '<td valign="top">Now that is camouflage.  Very nice image with good framing.</td>', 'Now that is camouflage.  Very nice image with good framing.', '2014-11-12 10:03:18.000000', NULL, 1),
(7284697, 1134947, 170281, '<td valign="top">I like the image, but I am sure I understand the camouflage concept.</td>', 'I like the image, but I am sure I understand the camouflage concept.', '2014-11-12 10:20:40.000000', NULL, 1),
(7284701, 1135158, 170281, '<td valign="top">Can you share where this image was taken?  If deployed, stay safe and thanks for your service.</td>', 'Can you share where this image was taken?  If deployed, stay safe and thanks for your service.', '2014-11-12 10:24:29.000000', NULL, 1),
(7284718, 1135309, 16046, '<td valign="top">Best in show award, congrats</td>', 'Best in show award, congrats', '2014-11-12 10:50:17.000000', NULL, 1),
(7284719, 1135335, 16046, '<td valign="top">Top 3</td>', 'Top 3', '2014-11-12 10:50:37.000000', NULL, 1),
(7284720, 1135353, 16046, '<td valign="top">Top 3</td>', 'Top 3', '2014-11-12 10:51:17.000000', NULL, 1),
(7284721, 1135242, 16046, '<td valign="top">Honorable mention</td>', 'Honorable mention', '2014-11-12 10:52:04.000000', NULL, 1),
(7285265, 1135069, 50864, '<td valign="top">I have been working with my pinhole lately and had decided that all I was getting for my trouble was a dirty sensor. You have just reminded me why it is worth the trouble. This is beautiful. 10</td>', 'I have been working with my pinhole lately and had decided that all I was getting for my trouble was a dirty sensor. You have just reminded me why it is worth the trouble. This is beautiful. 10', '2014-11-14 10:36:33.000000', NULL, 1),
(7285336, 1135342, 32011, '<td valign="top">This is my favourite image in the challenge.  I love the reflection and the processing... just the hint of colour.</td>', 'This is my favourite image in the challenge.  I love the reflection and the processing... just the hint of colour.', '2014-11-14 20:05:23.000000', NULL, 1),
(7285337, 1135230, 32011, '<td valign="top">Nice image. I like the shallow DOF very much,</td>', 'Nice image. I like the shallow DOF very much,', '2014-11-14 20:06:20.000000', NULL, 1),
(7285338, 1135304, 32011, '<td valign="top">This is a very clever take on the challenge... one of my favourites.</td>', 'This is a very clever take on the challenge... one of my favourites.', '2014-11-14 20:07:10.000000', NULL, 1),
(7285339, 1135270, 32011, '<td valign="top">While I''ve long admired the squirrel''s ninja acrobatics, I''ve never appreciated the camouflage aspects.  Beautiful image, outstanding composition.</td>', 'While I''ve long admired the squirrel''s ninja acrobatics, I''ve never appreciated the camouflage aspects.  Beautiful image, outstanding composition.', '2014-11-14 20:09:00.000000', NULL, 1),
(7285340, 1135335, 32011, '<td valign="top">This is my pick for one of the ribbons.  Meets the challenge perfectly, beautifully composed, great colour.</td>', 'This is my pick for one of the ribbons.  Meets the challenge perfectly, beautifully composed, great colour.', '2014-11-14 20:09:55.000000', NULL, 1),
(7285341, 1135346, 32011, '<td valign="top">Wow.  Great image.  Reminds me of Han Solo in carbonite,  Excellent image for the challenge.</td>', 'Wow.  Great image.  Reminds me of Han Solo in carbonite,  Excellent image for the challenge.', '2014-11-14 20:11:19.000000', NULL, 1),
(7285342, 1135156, 32011, '<td valign="top">Nice composition. One of the better "artistic" images in the challenge.</td>', 'Nice composition. One of the better "artistic" images in the challenge.', '2014-11-14 20:12:16.000000', NULL, 1),
(7285343, 1135339, 32011, '<td valign="top">I like it.  I don''t imagine it will fair well with the masses, but this image makes me stop and contemplate what it is I''m looking at, and how it meets the challenge.  As art, it works well... it makes me think.</td>', 'I like it.  I don''t imagine it will fair well with the masses, but this image makes me stop and contemplate what it is I''m looking at, and how it meets the challenge.  As art, it works well... it makes me think.', '2014-11-14 20:14:44.000000', NULL, 1),
(7285344, 1135288, 32011, '<td valign="top">Nice and sharp.  Good use of shallow DOF.  Centred composition makes it a little static.</td>', 'Nice and sharp.  Good use of shallow DOF.  Centred composition makes it a little static.', '2014-11-14 20:16:14.000000', NULL, 1),
(7285346, 1135353, 32011, '<td valign="top">A nice capture.  A little too much going on which distracts a bit from the subject.</td>', 'A nice capture.  A little too much going on which distracts a bit from the subject.', '2014-11-14 20:17:07.000000', NULL, 1),
(7285347, 1135298, 32011, '<td valign="top">While I''m generally not a fan of cat photos, this is a very photo, and I like the leopard skin background making it very apt for the challenge.</td>', 'While I''m generally not a fan of cat photos, this is a very photo, and I like the leopard skin background making it very apt for the challenge.', '2014-11-14 20:18:22.000000', NULL, 1),
(7285348, 1135321, 32011, '<td valign="top">An interesting take on the challenge.  Would be interested how this would have done with the voters with some high or low key processing.</td>', 'An interesting take on the challenge.  Would be interested how this would have done with the voters with some high or low key processing.', '2014-11-14 20:21:15.000000', NULL, 1),
(7285349, 1135331, 32011, '<td valign="top">A nice image, and interesting spin on the camouflage theme... instead of nature''s use of it for defence/safety, it shows man''s use to defeat nature.  Nice work.</td>', 'A nice image, and interesting spin on the camouflage theme... instead of nature''s use of it for defence/safety, it shows man''s use to defeat nature.  Nice work.', '2014-11-14 20:22:54.000000', NULL, 1),
(7285350, 1134947, 32011, '<td valign="top">Nice composition.. she looks like Brittany Spears.</td>', 'Nice composition.. she looks like Brittany Spears.', '2014-11-14 20:23:56.000000', NULL, 1),
(7285351, 1134950, 32011, '<td valign="top">Nice detail.  Interesting choice on the composition... brave... I like it.</td>', 'Nice detail.  Interesting choice on the composition... brave... I like it.', '2014-11-14 20:25:04.000000', NULL, 1),
(7285352, 1135113, 32011, '<td valign="top">Snail on the leaf without the green stuff would possibly have worked a bit better for the challenge.  The snail camouflaged against the leaf is diminished somewhat, and one sees the snail and leaf on contrast to the green, which isn''t camouflaged all that well.</td>', 'Snail on the leaf without the green stuff would possibly have worked a bit better for the challenge.  The snail camouflaged against the leaf is diminished somewhat, and one sees the snail and leaf on contrast to the green, which isn''t camouflaged all that well.', '2014-11-14 20:27:41.000000', NULL, 1),
(7285353, 1135071, 32011, '<td valign="top">This looks like my backyard at times when I''ve waited too long to mow the lawn.  Nice composition and processing.</td>', 'This looks like my backyard at times when I''ve waited too long to mow the lawn.  Nice composition and processing.', '2014-11-14 20:28:35.000000', NULL, 1),
(7285354, 1135338, 32011, '<td valign="top">Hiding in a crowd of crocs... or, alligators... they look like alligators.</td>', 'Hiding in a crowd of crocs... or, alligators... they look like alligators.', '2014-11-14 20:29:30.000000', NULL, 1),
(7285355, 1135343, 32011, '<td valign="top">The red bird might be camouflaged well against autumn foliage, but come winter, these birds stick out like the dogs proverbials.</td>', 'The red bird might be camouflaged well against autumn foliage, but come winter, these birds stick out like the dogs proverbials.', '2014-11-14 20:31:36.000000', NULL, 1),
(7285356, 1135242, 32011, '<td valign="top">I have a suitcase with that pattern on it.</td>', 'I have a suitcase with that pattern on it.', '2014-11-14 20:32:32.000000', NULL, 1),
(7285653, 1135335, 13077, '<td valign="top">It blends in well, and nicely photographed.</td>', 'It blends in well, and nicely photographed.', '2014-11-16 16:42:01.000000', NULL, 1),
(7285654, 1135342, 13077, '<td valign="top">I suppose hiding behind things sort of counts. I wonder if this might have looked better in color?</td>', 'I suppose hiding behind things sort of counts. I wonder if this might have looked better in color?', '2014-11-16 16:43:37.000000', NULL, 1),
(7285655, 1135270, 13077, '<td valign="top">He''s on the wrong kind of tree to blend in, but they''re pretty good at staying alive so he''s probably fine.</td>', 'He''s on the wrong kind of tree to blend in, but they''re pretty good at staying alive so he''s probably fine.', '2014-11-16 16:44:21.000000', NULL, 1),
(7285656, 1135226, 13077, '<td valign="top">Not sure about relevance to the challenge but I like this a lot.</td>', 'Not sure about relevance to the challenge but I like this a lot.', '2014-11-16 16:45:01.000000', NULL, 1),
(7285657, 1135320, 13077, '<td valign="top">He thinks he can think green and become green! At least his eyes are pretty close...</td>', 'He thinks he can think green and become green! At least his eyes are pretty close...', '2014-11-16 16:52:30.000000', NULL, 1),
(7285661, 1135339, 13077, '<td valign="top">Whatever this is, the camouflage must be perfect because I can''t see it. lol</td>', 'Whatever this is, the camouflage must be perfect because I can''t see it. lol', '2014-11-16 17:02:57.000000', NULL, 1),
(7285696, 1135313, 13077, '<td valign="top">A beer in his pocket?</td>', 'A beer in his pocket?', '2014-11-16 21:57:11.000000', NULL, 1),
(7285698, 1135346, 13077, '<td valign="top">Nice art, and well photographed - the light &amp; shadows are just right.</td>', 'Nice art, and well photographed - the light & shadows are just right.', '2014-11-16 21:57:47.000000', NULL, 1),
(7285699, 1135288, 13077, '<td valign="top">That actually stands out quite a bit from the sand in my opinion.</td>', 'That actually stands out quite a bit from the sand in my opinion.', '2014-11-16 21:58:18.000000', NULL, 1),
(7285700, 1135291, 13077, '<td valign="top">If not for the doggone light, the shadow-man would be invisible!<br/> <br/>...oh wait...</td>', 'If not for the doggone light, the shadow-man would be invisible! ...oh wait...', '2014-11-16 21:58:46.000000', NULL, 1),
(7285702, 1135336, 13077, '<td valign="top">Maybe there isn''t?</td>', 'Maybe there isn''t?', '2014-11-16 21:59:05.000000', NULL, 1),
(7285704, 1135352, 13077, '<td valign="top">Pleasant arrangement of tones and shadowy patterns here.</td>', 'Pleasant arrangement of tones and shadowy patterns here.', '2014-11-16 21:59:36.000000', NULL, 1),
(7285706, 1135242, 13077, '<td valign="top">Nice - good concept, great setup and execution.</td>', 'Nice - good concept, great setup and execution.', '2014-11-16 22:01:04.000000', NULL, 1),
(7285708, 1135113, 13077, '<td valign="top">I like the darkness and the softness of this one, and all the shapes complement each other well. It''s so on the verge of being bad that it''s very good.</td>', 'I like the darkness and the softness of this one, and all the shapes complement each other well. It''s so on the verge of being bad that it''s very good.', '2014-11-16 22:02:02.000000', NULL, 1),
(7285710, 1135158, 13077, '<td valign="top">Meets the challenge pretty well, but the lamp post seemingly growing from the back of the vehicle is distracting.</td>', 'Meets the challenge pretty well, but the lamp post seemingly growing from the back of the vehicle is distracting.', '2014-11-16 22:03:34.000000', NULL, 1),
(7285712, 1135106, 13077, '<td valign="top">I don''t find it very attractive as a photo and I don''t get the concept or the title.</td>', 'I don''t find it very attractive as a photo and I don''t get the concept or the title.', '2014-11-16 22:04:16.000000', NULL, 1),
(7285714, 1135342, 113411, '<td valign="top">fabulous!!!!</td>', 'fabulous!!!!', '2014-11-16 22:04:46.000000', NULL, 1),
(7285715, 1134950, 13077, '<td valign="top">Nice detail shot, interesting how the patterns on his back look very much like a leaf. I think the photo could use a bit more contrast in post processing though.</td>', 'Nice detail shot, interesting how the patterns on his back look very much like a leaf. I think the photo could use a bit more contrast in post processing though.', '2014-11-16 22:04:55.000000', NULL, 1),
(7285716, 1135310, 13077, '<td valign="top">Great job on the processing with this one, also well composed and good light.</td>', 'Great job on the processing with this one, also well composed and good light.', '2014-11-16 22:05:23.000000', NULL, 1),
(7285718, 1135338, 113411, '<td valign="top">fabulous !!!!!!10!</td>', 'fabulous !!!!!!10!', '2014-11-16 22:06:25.000000', NULL, 1),
(7285719, 1135270, 113411, '<td valign="top">wow!!! great shot!</td>', 'wow!!! great shot!', '2014-11-16 22:06:44.000000', NULL, 1),
(7285721, 1135329, 13077, '<td valign="top">They are so well hidden I''ll just take your word on the count.</td>', 'They are so well hidden I''ll just take your word on the count.', '2014-11-16 22:08:08.000000', NULL, 1),
(7285722, 1135304, 13077, '<td valign="top">Nice concept and attractively composed.</td>', 'Nice concept and attractively composed.', '2014-11-16 22:08:29.000000', NULL, 1),
(7285723, 1135301, 13077, '<td valign="top">Cute - great light and well arranged and composed.</td>', 'Cute - great light and well arranged and composed.', '2014-11-16 22:08:44.000000', NULL, 1),
(7285724, 1135322, 13077, '<td valign="top">I suppose the branches are part of the concept, but visually it''s very busy and not very attractive in my opinion.</td>', 'I suppose the branches are part of the concept, but visually it''s very busy and not very attractive in my opinion.', '2014-11-16 22:09:16.000000', NULL, 1),
(7285726, 1135069, 13077, '<td valign="top">Mysteriously dark and eery, something about it seems to imply there is more than meets the eye.</td>', 'Mysteriously dark and eery, something about it seems to imply there is more than meets the eye.', '2014-11-16 22:11:34.000000', NULL, 1),
(7285727, 1135338, 13077, '<td valign="top">Cute - nicely composed with this sort of goofy looking guy''s head dead center.</td>', 'Cute - nicely composed with this sort of goofy looking guy''s head dead center.', '2014-11-16 22:12:03.000000', NULL, 1),
(7285728, 1135343, 13077, '<td valign="top">Despite being red he actually blends in alright next to the other pinecones.</td>', 'Despite being red he actually blends in alright next to the other pinecones.', '2014-11-16 22:12:46.000000', NULL, 1),
(7285729, 1135156, 13077, '<td valign="top">lol - yep, they always think they''re invisible.</td>', 'lol - yep, they always think they''re invisible.', '2014-11-16 22:13:12.000000', NULL, 1),
(7285730, 1135295, 13077, '<td valign="top">Nice patterns on the bird and good selection of a backdrop to shoot him against - he does get lost in the other shapes and colors nicely.</td>', 'Nice patterns on the bird and good selection of a backdrop to shoot him against - he does get lost in the other shapes and colors nicely.', '2014-11-16 22:13:54.000000', NULL, 1),
(7285732, 1135337, 13077, '<td valign="top">I get a propaganda film vibe from this one. Something interesting about it, it''s kept me looking at it for quite a while now...</td>', 'I get a propaganda film vibe from this one. Something interesting about it, it''s kept me looking at it for quite a while now...', '2014-11-16 22:22:02.000000', NULL, 1),
(7285734, 1135298, 13077, '<td valign="top">Nice looking cat, similar colorings as ours. Good choice of backdrop too, and it probably would blend in nicely if curled up asleep on that.</td>', 'Nice looking cat, similar colorings as ours. Good choice of backdrop too, and it probably would blend in nicely if curled up asleep on that.', '2014-11-16 22:23:10.000000', NULL, 1),
(7285735, 1134947, 13077, '<td valign="top">A lot of potential here but a few things let it down in my opinion. The lighting coming from the right really blows out her light skin and leaves the camo shirt quite dark,  there are some dirty parts of the floor surface in the shadow, and the crop on the right and the bottom feel awkward the way they have cut off part of her arm and the tips of her toes.</td>', 'A lot of potential here but a few things let it down in my opinion. The lighting coming from the right really blows out her light skin and leaves the camo shirt quite dark,  there are some dirty parts of the floor surface in the shadow, and the crop on the right and the bottom feel awkward the way they have cut off part of her arm and the tips of her toes.', '2014-11-16 22:25:25.000000', NULL, 1),
(7285738, 1135321, 13077, '<td valign="top">Very creepy vibe - excellent use of softness and dramatic light.</td>', 'Very creepy vibe - excellent use of softness and dramatic light.', '2014-11-16 22:34:29.000000', NULL, 1),
(7285739, 1135354, 13077, '<td valign="top">Looks so secret I''ll never even see what it is!</td>', 'Looks so secret I''ll never even see what it is!', '2014-11-16 22:35:00.000000', NULL, 1),
(7285740, 1134956, 13077, '<td valign="top">I looked up the word and the first result is that it''s like pleasantness/amenity? If so I don''t really get it...</td>', 'I looked up the word and the first result is that it''s like pleasantness/amenity? If so I don''t really get it...', '2014-11-16 22:36:19.000000', NULL, 1),
(7285741, 1135162, 13077, '<td valign="top">Good use of light and the scarf really makes this work.</td>', 'Good use of light and the scarf really makes this work.', '2014-11-16 22:36:48.000000', NULL, 1),
(7285742, 1135060, 13077, '<td valign="top">Excellent perspective, beautiful photo overall. And the colors of the bird really do blend in with the rest.</td>', 'Excellent perspective, beautiful photo overall. And the colors of the bird really do blend in with the rest.', '2014-11-16 22:37:25.000000', NULL, 1),
(7285743, 1134968, 13077, '<td valign="top">If something is in the midst of those leaves it must be camouflaged very well, I don''t see anything.</td>', 'If something is in the midst of those leaves it must be camouflaged very well, I don''t see anything.', '2014-11-16 22:38:08.000000', NULL, 1),
(7285744, 1135071, 13077, '<td valign="top">Very attractive shapes and tones in this one, it''s unusual but it works well.</td>', 'Very attractive shapes and tones in this one, it''s unusual but it works well.', '2014-11-16 22:38:40.000000', NULL, 1),
(7285745, 1135331, 13077, '<td valign="top">I like the overall feel of this - very nice tones and good detail.</td>', 'I like the overall feel of this - very nice tones and good detail.', '2014-11-16 22:39:00.000000', NULL, 1),
(7285746, 1135230, 13077, '<td valign="top">Very nice, well done.</td>', 'Very nice, well done.', '2014-11-16 22:39:19.000000', NULL, 1),
(7285747, 1135353, 13077, '<td valign="top">Good capture - excellent composition to show him blending in with both the snow and the leaves at the same time.</td>', 'Good capture - excellent composition to show him blending in with both the snow and the leaves at the same time.', '2014-11-16 22:39:43.000000', NULL, 1),
(7285748, 1135309, 13077, '<td valign="top">That''s cool - perfect find for the challenge!</td>', 'That''s cool - perfect find for the challenge!', '2014-11-16 22:39:46.000000', NULL, 1),
(7285909, 1135336, 150277, '<td valign="top">Wow, this is very subtle to my eyes.  But that purple is beautiful and I love the pop of yellow. You might help a girl out by highlighting the cat in your comments after the challenge is complete.  But I love the shot and found it very compelling, especially with the title.  (I can see a mouse, does that count?)</td>', 'Wow, this is very subtle to my eyes.  But that purple is beautiful and I love the pop of yellow. You might help a girl out by highlighting the cat in your comments after the challenge is complete.  But I love the shot and found it very compelling, especially with the title.  (I can see a mouse, does that count?)', '2014-11-17 21:43:21.000000', NULL, 1),
(7285911, 1135309, 150277, '<td valign="top">Wow, that''s cool.</td>', 'Wow, that''s cool.', '2014-11-17 21:44:56.000000', NULL, 1),
